:root {
  --bg: #1a1c2c;
  --card-bg: #2a2d4a;
  --primary: #f4d03f;
  --accent: #e74c3c;
  --text: #f0f0f0;
  --error: #ff6b6b;
  --border: #5d5f8a;
  --shadow: #0f0f1a;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  padding: 2rem;
  border-radius: 0;
  box-shadow: 8px 8px 0 var(--shadow);
  width: 100%;
  max-width: 480px;
  border: 4px solid var(--border);
}

.pixel-title {
  font-size: 1.8rem;
  text-align: center;
  margin-bottom: 1.5rem;
  color: var(--primary);
  text-shadow: 3px 3px 0 var(--shadow);
  letter-spacing: 2px;
  text-transform: uppercase;
}

.field {
  margin-bottom: 1.25rem;
}

label {
  display: block;
  font-weight: bold;
  margin-bottom: 0.4rem;
  color: var(--primary);
}

input {
  width: 100%;
  padding: 0.75rem;
  font-size: 1rem;
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  border-radius: 0;
  outline: none;
  transition: border-color 0.1s, box-shadow 0.1s;
}

input:hover {
  border-color: var(--primary);
}

input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(244, 208, 63, 0.4);
}

input:active {
  background: var(--shadow);
}

.error {
  color: var(--error);
  font-size: 0.85rem;
  display: block;
  margin-top: 0.25rem;
  min-height: 1.2em;
}

.pixel-btn {
  display: block;
  width: 100%;
  padding: 0.9rem;
  font-size: 1.2rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  background: var(--primary);
  color: var(--bg);
  border: none;
  border-bottom: 5px solid #b8941f;
  border-right: 5px solid #b8941f;
  cursor: pointer;
  transition: transform 0.05s, border-width 0.05s;
  margin-top: 0.5rem;
}

.pixel-btn:hover {
  background: #f7dc6f;
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.pixel-btn:active {
  transform: translate(3px, 3px);
  border-bottom-width: 2px;
  border-right-width: 2px;
}

.results {
  margin-top: 2rem;
  border-top: 3px dashed var(--border);
  padding-top: 1.5rem;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 0.5rem 0;
  font-size: 1.1rem;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.result-label {
  font-weight: bold;
  color: var(--primary);
}

.result-value {
  font-family: 'Courier New', monospace;
  font-weight: bold;
  font-size: 1.3rem;
  color: var(--text);
  background: var(--shadow);
  padding: 0.2rem 0.6rem;
  border: 2px solid var(--border);
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
  .pixel-title {
    font-size: 1.4rem;
  }
  .result-row {
    font-size: 1rem;
  }
  .result-value {
    font-size: 1.1rem;
  }
}

(function() {
  'use strict';

  const form = document.getElementById('loan-form');
  const amountInput = document.getElementById('amount');
  const rateInput = document.getElementById('rate');
  const yearsInput = document.getElementById('years');
  const amountError = document.getElementById('amount-error');
  const rateError = document.getElementById('rate-error');
  const yearsError = document.getElementById('years-error');
  const monthlyPaymentEl = document.getElementById('monthly-payment');
  const totalPaidEl = document.getElementById('total-paid');
  const totalInterestEl = document.getElementById('total-interest');

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function clearErrors() {
    amountError.textContent = '';
    rateError.textContent = '';
    yearsError.textContent = '';
  }

  function validate(amount, rate, years) {
    let valid = true;
    if (isNaN(amount) || amount <= 0) {
      amountError.textContent = 'Enter a positive loan amount.';
      valid = false;
    }
    if (isNaN(rate) || rate < 0) {
      rateError.textContent = 'Interest rate cannot be negative.';
      valid = false;
    }
    if (isNaN(years) || years <= 0) {
      yearsError.textContent = 'Loan term must be positive.';
      valid = false;
    }
    return valid;
  }

  function calculate(amount, annualRate, years) {
    const monthlyRate = annualRate / 100 / 12;
    const months = Math.round(years * 12);
    let monthlyPayment;

    if (monthlyRate === 0) {
      monthlyPayment = amount / months;
    } else {
      const factor = Math.pow(1 + monthlyRate, -months);
      monthlyPayment = amount * monthlyRate / (1 - factor);
    }

    const totalPaid = monthlyPayment * months;
    const totalInterest = totalPaid - amount;

    return {
      monthlyPayment: monthlyPayment,
      totalPaid: totalPaid,
      totalInterest: totalInterest
    };
  }

  function updateResults() {
    clearErrors();
    const amount = parseFloat(amountInput.value);
    const rate = parseFloat(rateInput.value);
    const years = parseFloat(yearsInput.value);

    if (!validate(amount, rate, years)) {
      monthlyPaymentEl.textContent = '$0.00';
      totalPaidEl.textContent = '$0.00';
      totalInterestEl.textContent = '$0.00';
      return;
    }

    const result = calculate(amount, rate, years);
    monthlyPaymentEl.textContent = formatCurrency(result.monthlyPayment);
    totalPaidEl.textContent = formatCurrency(result.totalPaid);
    totalInterestEl.textContent = formatCurrency(result.totalInterest);
  }

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    updateResults();
  });

  [amountInput, rateInput, yearsInput].forEach(function(input) {
    input.addEventListener('input', updateResults);
  });

  updateResults();
})();
